#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define MAX_TENANTS 64
#define REWARD_SCALE 1000000ULL
#define EPOCH_BLOCKS 100
#define MAX_STAKE UINT64_MAX

typedef struct {
    uint64_t tenant_id;
    uint64_t total_staked;
    uint64_t reward_per_token_stored;
    uint64_t last_update_block;
    uint64_t reward_rate;
} TenantPool;

typedef struct {
    uint64_t tenant_id;
    uint64_t user_id;
    uint64_t balance;
    uint64_t rewards_paid;
    uint64_t user_reward_per_token_paid;
} UserStake;

static TenantPool pools[MAX_TENANTS];
static UserStake stakes[MAX_TENANTS * 256];
static uint64_t current_block = 0;
static int num_pools = 0;
static int num_stakes = 0;

static int find_pool(uint64_t tenant_id) {
    for (int i = 0; i < num_pools; i++) {
        if (pools[i].tenant_id == tenant_id) return i;
    }
    return -1;
}

static int find_stake(uint64_t tenant_id, uint64_t user_id) {
    for (int i = 0; i < num_stakes; i++) {
        if (stakes[i].tenant_id == tenant_id && stakes[i].user_id == user_id)
            return i;
    }
    return -1;
}

/* Compute reward accrued per token since last update.
 * Uses fixed-point arithmetic with REWARD_SCALE precision.
 * Isolation: each tenant pool tracks its own reward state independently.
 * Uses __uint128_t to prevent intermediate overflow in multiplication.
 */
static uint64_t compute_reward_per_token(int pool_idx) {
    TenantPool *pool = &pools[pool_idx];
    if (pool->total_staked == 0) {
        return pool->reward_per_token_stored;
    }
    uint64_t blocks_elapsed = current_block - pool->last_update_block;
    /* Calculate: reward_rate * blocks_elapsed * REWARD_SCALE / total_staked
     * Use 128-bit intermediate to prevent overflow.
     */
    __uint128_t numerator = (__uint128_t)pool->reward_rate * blocks_elapsed;
    __uint128_t scaled = (numerator * REWARD_SCALE) / pool->total_staked;
    /* Cap at max uint64 to prevent truncation-based exploits */
    if (scaled > UINT64_MAX) return UINT64_MAX;
    uint64_t result = pool->reward_per_token_stored + (uint64_t)scaled;
    /* Check for addition overflow */
    if (result < pool->reward_per_token_stored) return UINT64_MAX;
    return result;
}

static uint64_t compute_earned(int pool_idx, int stake_idx) {
    uint64_t current_rpt = compute_reward_per_token(pool_idx);
    UserStake *s = &stakes[stake_idx];
    uint64_t delta = current_rpt - s->user_reward_per_token_paid;
    /* earned = balance * delta / REWARD_SCALE + rewards_paid */
    __uint128_t product = (__uint128_t)s->balance * delta;
    uint64_t earned_delta = (uint64_t)(product / REWARD_SCALE);
    /* Check addition overflow */
    if (earned_delta > UINT64_MAX - s->rewards_paid) return UINT64_MAX;
    uint64_t earned = earned_delta + s->rewards_paid;
    return earned;
}

int create_pool(uint64_t tenant_id, uint64_t reward_rate) {
    if (num_pools >= MAX_TENANTS) return -1;
    if (find_pool(tenant_id) >= 0) return -1;
    pools[num_pools].tenant_id = tenant_id;
    pools[num_pools].total_staked = 0;
    pools[num_pools].reward_per_token_stored = 0;
    pools[num_pools].last_update_block = current_block;
    pools[num_pools].reward_rate = reward_rate;
    num_pools++;
    return 0;
}

int stake_tokens(uint64_t tenant_id, uint64_t user_id, uint64_t amount) {
    if (amount == 0) return -1;
    int pidx = find_pool(tenant_id);
    if (pidx < 0) return -1;

    /* Update pool reward state before modifying stakes */
    pools[pidx].reward_per_token_stored = compute_reward_per_token(pidx);
    pools[pidx].last_update_block = current_block;

    int sidx = find_stake(tenant_id, user_id);
    if (sidx < 0) {
        if (num_stakes >= MAX_TENANTS * 256) return -1;
        sidx = num_stakes++;
        stakes[sidx].tenant_id = tenant_id;
        stakes[sidx].user_id = user_id;
        stakes[sidx].balance = 0;
        stakes[sidx].rewards_paid = 0;
        stakes[sidx].user_reward_per_token_paid = 0;
    }

    /* Update user rewards before balance change */
    stakes[sidx].rewards_paid = compute_earned(pidx, sidx);
    stakes[sidx].user_reward_per_token_paid = pools[pidx].reward_per_token_stored;

    /* Check tenant isolation: total_staked overflow protection */
    if (pools[pidx].total_staked + amount < pools[pidx].total_staked) return -1;
    /* Also check user balance overflow */
    if (stakes[sidx].balance + amount < stakes[sidx].balance) return -1;

    stakes[sidx].balance += amount;
    pools[pidx].total_staked += amount;
    return 0;
}

uint64_t claim_rewards(uint64_t tenant_id, uint64_t user_id) {
    int pidx = find_pool(tenant_id);
    if (pidx < 0) return 0;

    pools[pidx].reward_per_token_stored = compute_reward_per_token(pidx);
    pools[pidx].last_update_block = current_block;

    int sidx = find_stake(tenant_id, user_id);
    if (sidx < 0) return 0;

    uint64_t earned = compute_earned(pidx, sidx);
    stakes[sidx].rewards_paid = 0;
    stakes[sidx].user_reward_per_token_paid = pools[pidx].reward_per_token_stored;
    return earned;
}

void advance_block(uint64_t blocks) {
    current_block += blocks;
}

/* Cross-tenant reward isolation verification.
 * Each tenant's reward calculation is independent.
 */
int verify_isolation(uint64_t tenant_a, uint64_t tenant_b) {
    int pa = find_pool(tenant_a);
    int pb = find_pool(tenant_b);
    if (pa < 0 || pb < 0) return -1;
    /* Pools are independent - modifying one doesn't affect the other */
    return (pools[pa].reward_per_token_stored != pools[pb].reward_per_token_stored) ? 1 : 0;
}
